const cookieCache = {
    aliyun: { value: null, timestamp: 0 },
    quark: { value: null, timestamp: 0 },
    uc: { value: null, timestamp: 0 },
    guangya: { value: null, timestamp: 0 }
};

// Cookie 有效期：24小时
const COOKIE_MAX_AGE = 24 * 60 * 60 * 1000;
const memoryStore = new Map();

// ============================== 蓝奏云内存Session缓存 ==============================
const lanzouSessionCache = new Map();
const LANZOU_SESSION_TTL = 5 * 60 * 1000;

function saveLanzouSession(shareId, sessionData) {
    lanzouSessionCache.set(shareId, {
        cookies: sessionData.cookies || '',
        fid: sessionData.fid || '',
        t: sessionData.t || '',
        k: sessionData.k || '',
        uid: sessionData.uid || '',
        pwd: sessionData.pwd || '',
        createdAt: Date.now()
    });
    console.log('[LZ Session]  保存session到内存, shareId=', shareId, ', Cookie长度:', (sessionData.cookies || '').length);
}

function getLanzouSession(shareId) {
    const session = lanzouSessionCache.get(shareId);
    if (!session) return null;
    if (Date.now() - session.createdAt > LANZOU_SESSION_TTL) {
        lanzouSessionCache.delete(shareId);
        console.log('[LZ Session] ⏰ session已过期并清除, shareId=', shareId);
        return null;
    }
    console.log('[LZ Session]  从内存读取session成功, shareId=', shareId);
    return session;
}

function buildLanzouCookie(pageCookies) {
    if (!pageCookies) return '';
    const parts = pageCookies.split(';').map(s => s.trim()).filter(s => s);
    const seen = {};
    const deduped = [];
    for (const p of parts) {
        const name = p.split('=')[0].trim();
        if (!seen[name]) {
            seen[name] = true;
            deduped.push(p);
        }
    }
    return deduped.join('; ');
}

// ============================== 蓝奏云优享版内存Session缓存 ==============================
