const DESKTOP_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';

function lanzouRandIP() {
    const prefixes = ['218','218','66','66','218','218','60','60','202','204','66','66','66','59','61','60','222','221','66','59','60','60','66','218','218','62','63','64','66','66','122','211'];
    return prefixes[Math.floor(Math.random() * prefixes.length)] + '.'
        + Math.floor(Math.random() * 256) + '.'
        + Math.floor(Math.random() * 256) + '.'
        + Math.floor(Math.random() * 256);
}

class LanzouSession {
    constructor() {
        this.cookies = new Map();
        this.cookieOrder = [];
    }

    extractSetCookies(resp) {
        let cookieList = [];
        if (typeof resp.headers.getSetCookie === 'function') {
            try { cookieList = resp.headers.getSetCookie(); } catch(e) { cookieList = []; }
        }
        if (!cookieList.length) {
            resp.headers.forEach(function(val, key) {
                if (key.toLowerCase() === 'set-cookie') cookieList.push(val);
            });
        }
        return cookieList;
    }

    parseSetCookie(raw) {
        const cookieVal = raw.split(';')[0].trim();
        const eqIdx = cookieVal.indexOf('=');
        if (eqIdx <= 0) return null;
        const name = cookieVal.substring(0, eqIdx).trim();
        const value = cookieVal.substring(eqIdx + 1).trim();
        if (!/^[a-zA-Z_]/.test(name)) return null;
        return { name, value };
    }

    updateFromResponse(resp) {
        const rawCookies = this.extractSetCookies(resp);
        for (const raw of rawCookies) {
            const parsed = this.parseSetCookie(raw);
            if (parsed) {
                if (!this.cookies.has(parsed.name)) {
                    this.cookieOrder.push(parsed.name);
                }
                this.cookies.set(parsed.name, parsed.value);
            }
        }
        if (rawCookies.length > 0) {
            console.log('[LZ Session] 📥 收集到新Cookie:', this.getCookieString());
        }
    }

    getCookieString() {
        const parts = [];
        for (const name of this.cookieOrder) {
            if (this.cookies.has(name)) {
                parts.push(`${name}=${this.cookies.get(name)}`);
            }
        }
        return parts.join('; ');
    }

    getHeaders(extraHeaders = {}) {
        const cookieStr = this.getCookieString();
        const headers = {
            'User-Agent': DESKTOP_UA,
            'X-Forwarded-For': lanzouRandIP(),
            'CLIENT-IP': lanzouRandIP(),
            ...extraHeaders
        };
        if (cookieStr) {
            headers['Cookie'] = cookieStr;
        }
        return headers;
    }

    async get(url, options = {}) {
        const headers = this.getHeaders(options.headers || {});
        console.log('[LZ Session] GET:', url.substring(0, 80), '| Cookie:', this.getCookieString() || '(无)');
        const resp = await fetch(url, { ...options, method: 'GET', headers, redirect: 'follow' });
        this.updateFromResponse(resp);
        return resp;
    }

    async post(url, body, options = {}) {
        const headers = this.getHeaders({
            'Content-Type': 'application/x-www-form-urlencoded',
            'X-Requested-With': 'XMLHttpRequest',
            ...(options.headers || {})
        });
        console.log('[LZ Session] POST:', url.substring(0, 80), '| Cookie:', this.getCookieString() || '(无)');
        const resp = await fetch(url, { ...options, method: 'POST', headers, body, redirect: 'follow' });
        this.updateFromResponse(resp);
        return resp;
    }
}

// ============================== Cookie 管理类 ==============================
class CookieManager {
    constructor(type, envValue) {
        this.type = type;
        this.envValue = envValue;
    }

    getValidCookie(forceRefresh = false) {
        const now = Date.now();
        const cached = cookieCache[this.type];

        console.log(`[${this.type}] getValidCookie调用, forceRefresh=${forceRefresh}, envValue长度=${this.envValue ? this.envValue.length : 0}`);
        console.log(`[${this.type}] 缓存状态:`, JSON.stringify({
            hasCachedValue: !!cached.value,
            cachedLength: cached.value ? cached.value.length : 0,
            cacheAge: cached.timestamp ? Math.floor((now - cached.timestamp) / 1000) + '秒' : '无'
        }));

        if (!forceRefresh && cached.value && (now - cached.timestamp) < COOKIE_MAX_AGE) {
            const remaining = COOKIE_MAX_AGE - (now - cached.timestamp);
            const remainingMinutes = Math.floor(remaining / 60000);
            console.log(`[${this.type}] 使用缓存的 Cookie，剩余有效期: ${remainingMinutes}分钟`);
            return {
                value: cached.value,
                isCached: true,
                expired: false,
                remainingTime: remaining
            };
        }

        if (this.envValue && typeof this.envValue === 'string' && this.envValue.length > 10) {
            const oldValue = cached.value;
            cookieCache[this.type] = {
                value: this.envValue,
                timestamp: now
            };
            console.log(`[${this.type}] Cookie 已更新${oldValue ? '（替换旧值）' : ''}, 新的24小时有效期开始计时, 长度=`, this.envValue.length);
            return {
                value: this.envValue,
                isCached: false,
                expired: false,
                remainingTime: COOKIE_MAX_AGE
            };
        }

        console.log(`[${this.type}]  无可用的有效Cookie! envValue=`, this.envValue ? (typeof this.envValue + ',len=' + String(this.envValue).length) : 'null/undefined');
        return {
            value: null,
            isCached: false,
            expired: true,
            remainingTime: 0
        };
    }

    invalidate() {
        cookieCache[this.type] = { value: null, timestamp: 0 };
        console.log(`[${this.type}] Cookie 已被标记为失效`);
    }

    getStatus() {
        const cached = cookieCache[this.type];
        const now = Date.now();

        if (!this.envValue) {
            return {
                configured: false,
                valid: false,
                message: '未配置环境变量'
            };
        }

        if (!cached.value) {
            return {
                configured: true,
                valid: true,
                cached: false,
                message: '已配置，尚未使用（将在首次请求时激活24小时有效期）'
            };
        }
        
        const age = now - cached.timestamp;
        const remaining = COOKIE_MAX_AGE - age;
        
        if (remaining > 0) {
            const remainingMinutes = Math.floor(remaining / 60000);
            const remainingSeconds = Math.floor((remaining % 60000) / 1000);
            return {
                configured: true,
                valid: true,
                cached: true,
                age: Math.floor(age / 1000),
                remaining: remainingMinutes * 60 + remainingSeconds,
                message: `Cookie 有效，剩余时间: ${remainingMinutes}分${remainingSeconds}秒`
            };
        } else {
            return {
                configured: true,
                valid: false,
                cached: true,
                expired: true,
                age: Math.floor(age / 1000),
                message: 'Cookie 已过期（超过24小时），请重新配置'
            };
        }
    }
}

// ============================== 全局Cookie缓存管理 ==============================
function clearAllCookieCache() {
    const types = ['aliyun', 'quark', 'uc', 'guangya'];
    types.forEach(type => {
        if (cookieCache[type]) {
            cookieCache[type] = { value: null, timestamp: 0 };
            console.log(`[全局缓存] 已清除 ${type} 的Cookie缓存`);
        }
    });
    console.log('[全局缓存]  所有云盘Cookie缓存已清除，下次请求将从D1重新读取');
}

function clearCookieCacheByType(type) {
    if (cookieCache[type]) {
        cookieCache[type] = { value: null, timestamp: 0 };
        console.log(`[全局缓存] 已清除 ${type} 的Cookie缓存`);
        return true;
    }
    return false;
}

